package eval

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/superops-team/okf/pkg/embeddings"
	"github.com/superops-team/okf/pkg/okf"
	"github.com/superops-team/okf/pkg/query"
	"github.com/superops-team/okf/pkg/vectorindex"
)

// chunkLevelBaselineArtifact is the auditable raw ordered fixture for the
// chunk-level hybrid S46 gate. It is regenerated by the test when
// OKF_UPDATE_BASELINE=1 and committed alongside the test. The gate asserts
// that the current pipeline produces metrics at or above this artifact
// (threshold mode) or within a tight tolerance (exact mode).
type chunkLevelBaseline struct {
	GoldenSet     string  `json:"golden_set"`
	KnowledgePath string  `json:"knowledge_path"`
	Strategy      string  `json:"strategy"`
	RecallAt5     float64 `json:"recall_at_5"`
	MRR           float64 `json:"mrr"`
	NDCGAt5       float64 `json:"ndcg_at_5"`
	PositiveCases int     `json:"positive_cases"`
}

// TestHybridBaselineGate_ChunkLevel is the machine-enforced non-regression
// gate for S46. It replicates the EXACT CLI chunk-level pipeline:
//
//	loadKnowledgeBundle → query.ConceptChunks → embed chunk.Text()
//	→ HNSW with ChunkKey(c, ordinal) → BuildLexicalBackend (BM25)
//	→ SemanticSearch with DefaultVectorWeight/DefaultLexicalWeight
//	→ Recall@5 / MRR / NDCG@5 against golden_semantic.json
//
// This is NOT a concept-level test (one vector per concept). It uses the
// same chunking, embedding, v3 chunk-key, and hybrid RRF fusion as
// `okf eval -compare` and `okf search`.
//
// Gate thresholds are conservative (Recall@5≥0.90, MRR≥0.60) so normal
// content drift does not flake, but a real regression (broken semantic
// channel, wrong weights, dedup bug, chunk-key mismatch) fails decisively.
func TestHybridBaselineGate_ChunkLevel(t *testing.T) {
	skipPuregoUnderRace(t)

	repoRoot := filepath.Join("..", "..")
	kbPath := filepath.Join(repoRoot, "docs", "knowledge")
	goldenPath := filepath.Join("testdata", "golden_semantic.json")
	artifactPath := filepath.Join("testdata", "hybrid_baseline_chunk_level.json")

	cases, err := LoadGoldenCases(goldenPath)
	if err != nil {
		t.Fatalf("load golden_semantic.json: %v", err)
	}

	okfBundle, err := okf.LoadBundle(kbPath, okf.DefaultLoadOptions())
	if err != nil {
		t.Fatalf("load docs/knowledge: %v", err)
	}
	qb := query.BundleFromOKF(okfBundle)
	if len(qb.Concepts) == 0 {
		t.Fatal("docs/knowledge bundle is empty")
	}

	emb, err := embeddings.NewMiniLM()
	if err != nil {
		t.Skipf("embedding model unavailable, skipping chunk-level hybrid gate: %v", err)
	}
	defer emb.Close()

	// Build chunk-level HNSW index — identical to cmdVectorIndex.
	idx := vectorindex.NewHNSW(emb.Dimension())
	chunkCount := 0
	for _, c := range qb.Concepts {
		for _, ch := range query.ConceptChunks(c) {
			vec, verr := emb.EmbedQuery(ch.Text())
			if verr != nil {
				t.Fatalf("embed %s chunk %d: %v", c.FilePath, ch.Ordinal, verr)
			}
			idx.Add(query.ChunkKey(c, ch.Ordinal), vec)
			chunkCount++
		}
	}
	if chunkCount == 0 {
		t.Fatal("no chunks indexed")
	}

	sem := &evalBackend{emb: emb, idx: idx}
	lex := query.BuildLexicalBackend(qb)

	// Hybrid strategy with default weights — same as CLI hybrid-default.
	hybrid := func(bundle *query.KnowledgeBundle, q string) []*query.Concept {
		opts := query.SearchOptions{TopK: 5, Lexical: lex}.
			WithVectorWeight(query.DefaultVectorWeight).
			WithLexicalWeight(query.DefaultLexicalWeight)
		res, serr := query.SemanticSearch(bundle, q, sem, opts)
		if serr != nil {
			return nil
		}
		out := make([]*query.Concept, 0, len(res))
		for _, r := range res {
			out = append(out, r.Concept)
		}
		return out
	}

	report := RunBenchmarkWith(qb, cases, 5, hybrid)
	agg := report.AggregateNonNegative

	t.Logf("chunk-level hybrid: Recall@5=%.4f MRR=%.4f NDCG@5=%.4f (positive=%d, chunks=%d)",
		agg.Recall, agg.MRR, agg.NDCG, report.PositiveCount, chunkCount)

	// S46 gate: hybrid Recall@5 and MRR must not drop below the reproducible
	// committed baseline. These thresholds are derived from the current-tree
	// chunk-level measurement (Recall@5≈0.92, MRR≈0.66) with margin.
	if agg.Recall < 0.90 {
		t.Errorf("S46 REGRESSION: chunk-level hybrid Recall@5=%.4f, want >= 0.90", agg.Recall)
	}
	if agg.MRR < 0.60 {
		t.Errorf("S46 REGRESSION: chunk-level hybrid MRR=%.4f, want >= 0.60", agg.MRR)
	}

	// Save / verify auditable baseline artifact.
	artifact := chunkLevelBaseline{
		GoldenSet:     goldenPath,
		KnowledgePath: kbPath,
		Strategy:      "hybrid-default (chunk-level, v3 keys)",
		RecallAt5:     agg.Recall,
		MRR:           agg.MRR,
		NDCGAt5:       agg.NDCG,
		PositiveCases: report.PositiveCount,
	}
	if os.Getenv("OKF_UPDATE_BASELINE") == "1" {
		data, _ := json.MarshalIndent(artifact, "", "  ")
		if werr := os.WriteFile(artifactPath, data, 0644); werr != nil {
			t.Fatalf("write baseline artifact: %v", werr)
		}
		t.Logf("updated baseline artifact: %s", artifactPath)
	} else {
		data, rerr := os.ReadFile(artifactPath)
		if rerr == nil {
			var saved chunkLevelBaseline
			if jerr := json.Unmarshal(data, &saved); jerr == nil {
				t.Logf("committed baseline artifact: Recall@5=%.4f MRR=%.4f", saved.RecallAt5, saved.MRR)
				// Current must not be below committed artifact.
				if agg.Recall < saved.RecallAt5-0.02 {
					t.Errorf("S46 REGRESSION vs artifact: Recall@5=%.4f, committed=%.4f (tolerance 0.02)",
						agg.Recall, saved.RecallAt5)
				}
				if agg.MRR < saved.MRR-0.03 {
					t.Errorf("S46 REGRESSION vs artifact: MRR=%.4f, committed=%.4f (tolerance 0.03)",
						agg.MRR, saved.MRR)
				}
			}
		}
	}

	// --- Negative controls: gate must FAIL when retrieval is broken ---
	t.Run("broken_semantic_channel_fails", func(t *testing.T) {
		// Zero vector weight → lexical-only → Recall@5 should drop below gate.
		lexOnly := func(bundle *query.KnowledgeBundle, q string) []*query.Concept {
			opts := query.SearchOptions{TopK: 5, Lexical: lex}.
				WithVectorWeight(0).WithLexicalWeight(query.DefaultLexicalWeight)
			res, _ := query.SemanticSearch(bundle, q, sem, opts)
			out := make([]*query.Concept, 0, len(res))
			for _, r := range res {
				out = append(out, r.Concept)
			}
			return out
		}
		r := RunBenchmarkWith(qb, cases, 5, lexOnly)
		if r.AggregateNonNegative.Recall >= 0.90 {
			t.Errorf("gate should fail with broken semantic channel, got Recall@5=%.4f (>=0.90)",
				r.AggregateNonNegative.Recall)
		}
	})

	t.Run("wrong_weights_fails", func(t *testing.T) {
		// Inverted weights (lexical dominant) should not match hybrid baseline.
		inverted := func(bundle *query.KnowledgeBundle, q string) []*query.Concept {
			opts := query.SearchOptions{TopK: 5, Lexical: lex}.
				WithVectorWeight(0.1).WithLexicalWeight(1.0)
			res, _ := query.SemanticSearch(bundle, q, sem, opts)
			out := make([]*query.Concept, 0, len(res))
			for _, r := range res {
				out = append(out, r.Concept)
			}
			return out
		}
		r := RunBenchmarkWith(qb, cases, 5, inverted)
		// Inverted weights may still pass recall (lexical can find some), but
		// MRR should differ from hybrid. We assert the gate logic catches a
		// deliberately broken config by checking it's NOT identical to hybrid.
		if r.AggregateNonNegative.MRR == agg.MRR && r.AggregateNonNegative.Recall == agg.Recall {
			t.Error("inverted weights produced identical metrics to hybrid — gate cannot discriminate")
		}
	})
}
